(() => {
  const dw = window.DRIFTWING;
  const { ctx, state } = dw;
  if (!dw.debug) throw new Error('the view physics check needs the dev hooks (a dev build, ?debug=1 or ?test)');
  const FRAMES = 240;
  // Runs from the same start with the same inputs are identical; the tolerance only allows for
  // floating-point rounding. Anything the view fed into the physics shows as millimetres or more
  // (a 0.1 % rudder leak in one view moves every craft by 0.7 mm to 15 cm in these 240 frames).
  // Positions in m, velocities in m/s, quaternion units.
  const TOLERANCE = 1e-9;
  const YIELD_EVERY = 20;
  const canvas = ctx.renderer.domElement;
  const key = (type, code) => window.dispatchEvent(new KeyboardEvent(type, { code, key: code, bubbles: true, cancelable: true }));
  const press = (code) => { key('keydown', code); key('keyup', code); };
  const pointer = (target, type, init) => target.dispatchEvent(new PointerEvent(type, { pointerId: 7, pointerType: 'mouse', isPrimary: true, bubbles: true, cancelable: true, clientX: 640, clientY: 360, ...init }));
  const RELEASED_KEYS = ['ArrowUp', 'KeyD', 'KeyE', 'KeyW', 'KeyA', 'KeyV', 'KeyC', 'Numpad4'];
  // The pilot's inputs by frame, the same in every run: pitch, roll, rudder, throttle and roll back.
  const PILOT = new Map([
    [10, () => key('keydown', 'ArrowUp')], [70, () => key('keyup', 'ArrowUp')],
    [40, () => key('keydown', 'KeyD')], [100, () => key('keyup', 'KeyD')],
    [90, () => key('keydown', 'KeyE')], [150, () => key('keyup', 'KeyE')],
    [120, () => key('keydown', 'KeyW')], [160, () => key('keyup', 'KeyW')],
    [170, () => key('keydown', 'KeyA')], [215, () => key('keyup', 'KeyA')],
  ]);
  // Free look in every run: a right-drag (ControlState lookX / lookY) and a 90 degree look snap.
  function look(frame) {
    if (frame === 50) pointer(canvas, 'pointerdown', { button: 2, buttons: 2 });
    else if (frame > 50 && frame < 110) pointer(document, 'pointermove', { button: -1, buttons: 2, movementX: 6, movementY: frame < 80 ? -3 : 3 });
    else if (frame === 110) pointer(document, 'pointerup', { button: 2, buttons: 0 });
    if (frame === 60 || frame === 130) press('Numpad4');
  }
  // The switching run only: the first / third person swap (V) and the view cycle (C), in flight,
  // through chase, cockpit, wing and flyby (V from the cockpit returns to the last outside view).
  const SWITCHES = new Map([[30, 'KeyV'], [60, 'KeyC'], [80, 'KeyC'], [105, 'KeyV'], [135, 'KeyV'], [165, 'KeyC'], [195, 'KeyV'], [225, 'KeyV']]);

  function releaseAll() {
    for (const code of RELEASED_KEYS) key('keyup', code);
    pointer(document, 'pointerup', { button: 2, buttons: 0 });
  }

  /**
   * One run: the same start and the same inputs, from the given view; returns the trajectory. The
   * craft is rebuilt at the start point for every run, so its flight model begins from a fresh,
   * identically trimmed state rather than from whatever the last run left in its filters: a detour
   * craft whose model kind has no trim (the drone or the helicopter) is reset exactly onto the start
   * pose, and the craft under test is built from there.
   */
  async function run(start, view, switching) {
    const flight = ctx.systems.flight;
    const camera = ctx.systems.camera;
    const input = ctx.systems.input;
    releaseAll();
    input.touch.setThrottle(0.6);
    dw.debug.resetTiming();
    dw.debug.stepFrames(2);
    input.touch.releaseThrottle();
    dw.debug.stepFrames(1);
    // Back to the start time. One frame without physics time lets the clouds refresh the wind
    // strength uniform the wind field reads, so the start pose sees the same air in every run.
    state.time.elapsed = start.elapsed - 1 / 60;
    state.time.dayTime = start.dayTime;
    dw.debug.resetTiming();
    dw.debug.stepFrames(1);
    ctx.settings.set('craft', start.detour);
    flight.resetTo({ x: start.x, y: start.y, z: start.z, heading: start.heading });
    ctx.settings.set('craft', start.craft);
    camera.setView(view);
    dw.debug.resetTiming();
    const model = flight.getModel();
    const body0 = model.state;
    const initial = [body0.position.x, body0.position.y, body0.position.z, body0.velocity.x, body0.velocity.y, body0.velocity.z,
      body0.quaternion.x, body0.quaternion.y, body0.quaternion.z, body0.quaternion.w, ctx.controls.throttle, ctx.controls.collective, ctx.controls.trim];
    const tick0 = state.flight.tick;
    const rows = [];
    const views = new Set([camera.getView()]);
    let lookSeen = 0;
    for (let frame = 0; frame < FRAMES; frame++) {
      PILOT.get(frame)?.();
      look(frame);
      if (switching && SWITCHES.has(frame)) press(SWITCHES.get(frame));
      dw.debug.stepFrames(1);
      views.add(camera.getView());
      lookSeen = Math.max(lookSeen, Math.abs(ctx.controls.lookX));
      const body = model.state;
      rows.push([state.flight.tick - tick0, body.position.x, body.position.y, body.position.z, body.velocity.x, body.velocity.y, body.velocity.z,
        body.quaternion.x, body.quaternion.y, body.quaternion.z, body.quaternion.w, body.angularVelocity.x, body.angularVelocity.y, body.angularVelocity.z]);
      if (frame % YIELD_EVERY === YIELD_EVERY - 1) await new Promise((resolve) => setTimeout(resolve, 0));
    }
    releaseAll();
    return { view, initial, rows, views: [...views], lookSeen, ticks: rows[rows.length - 1][0] };
  }

  /** Largest difference between two runs (ticks must match frame for frame). */
  function compare(first, second) {
    let maxDifference = 0;
    let tickMismatch = 0;
    for (let index = 0; index < first.rows.length; index++) {
      const a = first.rows[index];
      const b = second.rows[index];
      if (a[0] !== b[0]) tickMismatch++;
      for (let column = 1; column < a.length; column++) maxDifference = Math.max(maxDifference, Math.abs(a[column] - b[column]));
    }
    const startDifference = Math.max(...first.initial.map((value, column) => Math.abs(value - second.initial[column])));
    return { maxDifference, tickMismatch, startDifference };
  }

  const results = [];
  window.__viewPhysics = {
    results,
    /**
     * Flies craft four times from one start, well clear of the terrain: cockpit, chase, chase with
     * view switches, and the cockpit again (the control: what two identical runs differ by).
     */
    async check(craft) {
      ctx.settings.set('craft', craft);
      dw.debug.stepFrames(20);
      const player = state.player;
      const ground = ctx.world.groundHeight(player.position.x, player.position.z);
      const start = { craft, detour: craft === 'fpv' ? 'helicopter' : 'fpv', x: player.position.x, y: Math.max(ground + 1200, 2500), z: player.position.z, heading: player.heading, elapsed: state.time.elapsed, dayTime: state.time.dayTime };
      const cockpit = await run(start, 'cockpit', false);
      const chase = await run(start, 'chase', false);
      const switching = await run(start, 'chase', true);
      const repeat = await run(start, 'cockpit', false);
      const pairs = { chase: compare(cockpit, chase), switching: compare(cockpit, switching), repeat: compare(cockpit, repeat) };
      const passed = Object.values(pairs).every((pair) => pair.startDifference <= TOLERANCE && pair.tickMismatch === 0 && pair.maxDifference <= TOLERANCE)
        && cockpit.views.every((view) => view === 'cockpit' || view === 'fpv') && chase.views.every((view) => view === 'chase')
        && switching.views.length >= 4 && cockpit.lookSeen > 0.2 && cockpit.ticks > FRAMES;
      const line = `${passed ? 'PASS' : 'FAIL'} ${craft}: ${FRAMES} frames, ${cockpit.ticks} ticks; cockpit (${cockpit.views.join('/')}) vs chase: max difference ${pairs.chase.maxDifference.toExponential(1)}, ticks off ${pairs.chase.tickMismatch}; vs switching (${switching.views.join(', ')}): ${pairs.switching.maxDifference.toExponential(1)}, ticks off ${pairs.switching.tickMismatch}; cockpit again: ${pairs.repeat.maxDifference.toExponential(1)}; start spread ${Math.max(pairs.chase.startDifference, pairs.switching.startDifference, pairs.repeat.startDifference).toExponential(1)}; tolerance ${TOLERANCE}; free look ${cockpit.lookSeen.toFixed(2)}`;
      results.push({ craft, passed, line });
      if (!passed) console.error(`[view physics] ${line}`);
      return line;
    },
  };
  ctx.settings.set('timeFrozen', true);
  dw.debug.pauseLoop();
  return 'view physics check ready: loop paused, time frozen';
})()

(() => {
  const { results } = window.__viewPhysics;
  window.DRIFTWING.debug.resumeLoop();
  window.DRIFTWING.ctx.settings.set('timeFrozen', false);
  const failed = results.filter((result) => !result.passed).length;
  if (results.length !== 6 || failed > 0) console.error(`[view physics] ${failed} of ${results.length} craft failed`);
  return `view physics: ${results.length - failed}/${results.length} craft fly identically in every view`;
})()
